# IS THE DOUBLED-CHAIN LINDBLADIAN THE OPERATOR WE THINK IT IS?  (NO SOLVER INVOLVED)
#
# The ket-half diagnostic failed (1.489e-01) while `pair_mpo`-vs-`xxz_mpo` passed exactly, which
# leaves two suspects that a TIME-EVOLUTION test cannot tell apart: a wrong OPERATOR or a wrong
# non-Hermitian SOLVER. This separates them by comparing the MPO to the dense superoperator as an
# OPERATOR -- `<v|W|v>` from `mpo_energy` against `dv' * W_chain * dv` -- with no `expv` anywhere.
#
# ⚠ PROBE STATES ARE GENERATED BY A SOLVER, AND THAT IS FINE. Any generic state probes the
# operator; whether the generator is accurate is irrelevant, so the probes come from `tdvp2` under
# a HERMITIAN chain MPO (its trusted path). What is NOT fine is a product state: the XY part is
# purely off-diagonal, so `<a|W|a> = 0` for both the right and the wrong operator.
#
# ⛔ AND THE BASES DIFFER. `dense_state` interleaves ket/bra bits with chain site 1 as MSB; the
# dense superoperator is column-stacked `(b-1)*D + a`. The permutation between them is applied to
# the dense matrix, not assumed away.
using LinearAlgebra, Printf
using LurCGT, Telum
using BUGJulia
using BUGJulia.BondUpdateBUG
using BUGJulia.RSVDCBEBondUpdate
include(joinpath(@__DIR__, "..", "tests", "common", "dense_reference.jl"))

const L = 3; const N = 2L; const D = 2^L
const OUT = joinpath(@__DIR__, "results", "mpo_vs_dense.txt"); mkpath(dirname(OUT))
io = open(OUT, "w"); say(l) = (println(io, l); flush(io); println(stdout, l); flush(stdout))
set_symmetry!(:none)

const SX = ComplexF64[0 .5; .5 0]; const SY = ComplexF64[0 -.5im; .5im 0]
const SZ = ComplexF64[.5 0; 0 -.5];  const ID = ComplexF64[1 0; 0 1]
function site_op(op, j, L)
    m = ComplexF64[1;;]; for k in 1:L; m = kron(m, k == j ? op : ID); end; m
end
ket(j) = 2j - 1; bra(j) = 2j
const JM = [abs(i - j) == 1 && i < j ? 1.0 : 0.0 for i in 1:L, j in 1:L]
const HD = sum(JM[i,j] * (site_op(SX,i,L)*site_op(SX,j,L) + site_op(SY,i,L)*site_op(SY,j,L))
               for i in 1:L for j in (i+1):L if JM[i,j] != 0.0)

"Chain index -> flat column-stacked index `(b-1)*D + a`."
function chain_to_vec(idx)
    a = 0; b = 0
    for j in 1:L
        a |= ((idx >> (N - ket(j))) & 1) << (L - j)
        b |= ((idx >> (N - bra(j))) & 1) << (L - j)
    end
    return b * D + a + 1
end
const PERM = [chain_to_vec(idx) for idx in 0:(4^L - 1)]

"Dense superoperator, in the CHAIN basis, for the requested pieces."
function dense_super(; ket_h::Bool, bra_h::Bool, gamma::Float64)
    S = zeros(ComplexF64, D*D, D*D)
    for a in 1:D, b in 1:D
        E = zeros(ComplexF64, D, D); E[a, b] = 1.0
        R = zeros(ComplexF64, D, D)
        ket_h && (R -= im * (HD * E))
        bra_h && (R += im * (E * HD))
        if gamma != 0.0
            for j in 1:L
                Z = site_op(SZ, j, L)
                R += gamma * (Z*E*Z - 0.5*(Z*Z*E + E*Z*Z))
            end
        end
        S[:, (b-1)*D + a] = vec(R)
    end
    return S[PERM, PERM]
end

"Per-vertex couplings on the doubled chain for the requested pieces."
function couplings(; ket_h::Bool, bra_h::Bool, gamma::Float64, v)
    izz = findall(t -> t.left === t.right, v); length(izz) == 1 || error("vertex count")
    Jh = zeros(ComplexF64, N, N)
    for i in 1:L, j in (i+1):L
        JM[i,j] == 0.0 && continue
        # ⛔ `cond && (x = ...; y = ...)` is a TUPLE WITH A SEMICOLON to the parser, not a block:
        #    "syntax: unexpected semicolon in tuple". `begin ... end` is the block form.
        if ket_h
            a, b = minmax(ket(i), ket(j)); Jh[a, b] += -im * JM[i, j]
        end
        if bra_h
            c, d = minmax(bra(i), bra(j)); Jh[c, d] += +im * JM[i, j]
        end
    end
    Js = Any[copy(Jh) for _ in v]
    Jz = 0.0 .* Jh                                   # delta = 0 -> XX, no S^zS^z in H
    for j in 1:L
        a, b = minmax(ket(j), bra(j)); Jz[a,b] += gamma
    end
    Js[izz[1]] = Jz
    return Vector{AbstractMatrix}(Js)
end

# ── generic probe states: tdvp2 under a HERMITIAN doubled-chain MPO ────────────────────────
const WPROBE = xxz_mpo(N; J = 1.0, delta = 1.0)
function probes(n)
    out = Any[]
    p = product_state([:up, :up, :down, :up, :up, :down][1:N])
    for k in 1:n
        for _ in 1:2
            tdvp2_step!(p, WPROBE, ComplexF64(-0.37im); maxdim = 256, trunc_thresh = 1e-14,
                        maxiter = 24)
        end
        push!(out, copy(p))
    end
    return out
end
const PS = probes(6)
say(@sprintf("L = %d system sites -> %d chain sites, dim %d; %d probe states", L, N, 4^L,
             length(PS)))
say("")
say(@sprintf("  %-26s %14s %14s", "piece of the Lindbladian", "max rel dev", "verdict"))
for (name, kw) in (("ket half   -i(H(x)I)",  (ket_h=true,  bra_h=false, gamma=0.0)),
                   ("bra half   +i(I(x)H^T)",(ket_h=false, bra_h=true,  gamma=0.0)),
                   ("both halves, gamma=0",  (ket_h=true,  bra_h=true,  gamma=0.0)),
                   ("full, gamma=0.5",       (ket_h=true,  bra_h=true,  gamma=0.5)))
    Sd = dense_super(; kw...)
    v  = pair_vertices(xxz_chain(N; J = 1.0, delta = 1.0))
    W  = pair_mpo(N, couplings(; kw..., v = v), v)
    dev = 0.0
    for p in PS
        dv   = dense_state(p)
        want = dv' * Sd * dv
        got  = mpo_energy(p, W)
        dev  = max(dev, abs(got - want) / max(abs(want), 1e-12))
    end
    say(@sprintf("  %-26s %14.3e %14s", name, dev, dev < 1e-10 ? "PASS" : "FAIL"))
end
say("")
say("ALL PASS -> the MPO is correct and the fault is the non-Hermitian SOLVER path.")
say("ANY FAIL -> that piece of the operator is built wrong; the solver is off the hook.")
close(io)
